-- 00_PRECHECK — 조회 전용. [E20261012-DMF0082LATFIX] 적용 전 상태 판정 (전체 F5, 값 입력 없음)
-- * [L0] 접속 DB · PKG_DMF0082 BODY 상태·LAST_DDL (클라우드 10-12 09:03 실측 = 2026-10-09 12:08:07, 17032/885680)
-- * [L1] 패치 앵커 = VD 인라인뷰 ON 절 `AND p_division_id  = '82'` 줄 — 정확히 1줄이어야 10 적용 가능 (0 = 이미 다른 형태 / 2↑ = 원문 상이 → 중단)
-- * [L2] 마커 — 적용 전 0 (적용 뒤 2: VD 1 + History 1)
-- * [L3] 지금 커서에 남은 MF_SP INSERT(18xg1y5298qgq 계열) 계획의 lateral(VW_LAT) 존재 — 적용 전 Y 가 정상(= 고칠 대상)
-- * [L4] 지금 PKG_DMF0082 실행 중 세션 (있으면 끝난 뒤 10 실행 — CREATE OR REPLACE 가 library cache pin 대기)
SET LINESIZE 300 PAGESIZE 200
SELECT 'L0' CHK, SYS_CONTEXT('USERENV','DB_NAME') DB_NAME, SYS_CONTEXT('USERENV','INSTANCE_NAME') INST, TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI:SS') NOW FROM DUAL;
SELECT 'L0' CHK, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*)||'/'||SUM(LENGTH(RTRIM(TEXT, CHR(10)||CHR(13)))) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND LINE>1) BODY_FP
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0082' ORDER BY O.OBJECT_TYPE;
SELECT 'L1 앵커' CHK, COUNT(*) N, MIN(LINE) LINE,
       CASE WHEN COUNT(*) = 1 THEN 'PASS → 10 적용 가능' WHEN COUNT(*) = 0 THEN '❌ 앵커 없음 — 이미 적용(L2 확인) 또는 원문 상이 → 중단' ELSE '❌ 앵커 2줄↑ — 원문 상이 → 중단' END JUDGE
  FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%AND p_division_id  = ''82''%';
SELECT 'L1 앵커 문맥' CHK, LINE, RTRIM(TEXT, CHR(10)||CHR(13)) TXT FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY'
   AND LINE BETWEEN (SELECT MIN(LINE)-7 FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%AND p_division_id  = ''82''%')
                AND (SELECT MIN(LINE)+1 FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%AND p_division_id  = ''82''%')
 ORDER BY LINE;
SELECT 'L2 마커' CHK, COUNT(*) N, CASE WHEN COUNT(*) = 0 THEN '미적용 (기대)' WHEN COUNT(*) = 2 THEN '적용됨 — 10 재실행은 가드로 무동작' ELSE '⚠ 부분 적용 — 99 원복 후 재시도' END JUDGE
  FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%E20261012-DMF0082LATFIX%';
SELECT 'L3 MF_SP 계획' CHK, S.INST_ID, S.SQL_ID, S.CHILD_NUMBER CH, S.PLAN_HASH_VALUE PHV, S.EXECUTIONS EX, ROUND(S.ELAPSED_TIME/1e6/GREATEST(S.EXECUTIONS,1),1) SEC_PER_EX,
       ROUND(S.ROWS_PROCESSED/GREATEST(S.EXECUTIONS,1)) ROWS_PER_EX,
       CASE WHEN DBMS_LOB.INSTR(S.SQL_FULLTEXT, 'DIVISION_ID = ''82'' AND :B') > 0 THEN 'Y' ELSE 'N' END PATCHED_TXT,
       (SELECT COUNT(*) FROM GV$SQL_PLAN P WHERE P.INST_ID=S.INST_ID AND P.SQL_ID=S.SQL_ID AND P.CHILD_NUMBER=S.CHILD_NUMBER AND P.OBJECT_NAME LIKE 'VW_LAT%') VW_LAT,
       (SELECT COUNT(*) FROM GV$SQL_PLAN P WHERE P.INST_ID=S.INST_ID AND P.SQL_ID=S.SQL_ID AND P.CHILD_NUMBER=S.CHILD_NUMBER AND P.OPERATION='MERGE JOIN') MERGE_JOIN
  FROM GV$SQL S WHERE UPPER(S.SQL_TEXT) LIKE 'INSERT%INTO SCM_MGR.GT_DMF0082_MF_SP (%'
 ORDER BY S.LAST_ACTIVE_TIME DESC FETCH FIRST 5 ROWS ONLY;
-- PATCHED_TXT=N · VW_LAT=1 = 적용 전 문장(고칠 대상) / Y · 0 = 적용 뒤 문장
SELECT 'L4 실행중' CHK, S.INST_ID, S.SID, S.SERIAL#, S.USERNAME, S.MACHINE, S.LAST_CALL_ET CALL_SEC, S.SQL_ID
  FROM GV$SESSION S WHERE S.TYPE='USER' AND S.STATUS='ACTIVE'
   AND S.PLSQL_ENTRY_OBJECT_ID = (SELECT OBJECT_ID FROM USER_OBJECTS WHERE OBJECT_NAME='PKG_DMF0082' AND OBJECT_TYPE='PACKAGE')
 ORDER BY S.LAST_CALL_ET DESC;
